import { test } from 'node:test';
import { createState, frame, WIDTH, HEIGHT } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  beginPath: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1 - Ball should bounce off the top of a brick', () => {
  const state = createState(1);
  // Place ball just below the top edge of the first brick, moving UP
  const brick = state.bricks[0]; // top-left brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 0;
  state.ball.vy = -260; // Moving UP

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy > 0, true, 'Ball should have bounced DOWN');
});

