  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2; // Just to the left of the brick, but overlapping (R=7)
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 260; // Moving RIGHT
  state.ball.vy = 0;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx < 0, true, 'Ball should have bounced LEFT');
