import { createState, frame } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  beginPath: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1 - Ball should bounce off the top of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 0;
  state.ball.vy = -260; // Moving UP

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy > 0, true, 'Ball should have bounced DOWN');
  assert.strictEqual(state.ball.vx, 0, 'vx should not have changed');
});

test('D2 - Ball should bounce off the left side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2; // Overlap left side
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 260; // Moving RIGHT
  state.ball.vy = 0;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx < 0, true, 'Ball should have bounced LEFT');
  assert.strictEqual(state.ball.vy, 0, 'vy should not have changed');
});

test('D3 - Ball should be repositioned after bounce (No sticking)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 0;
  state.ball.vy = -260;

  frame(mockCtx, state);

  // After bounce, the ball should not be overlapping the brick anymore
  // Simple check: it should be above the brick top
  assert.strictEqual(state.ball.y - 7 <= brick.y, true, 'Ball should be pushed out of the brick');
});

# To Fix: Ball passes through bricks

Symptôme : « la balle traverse les briques au lieu de rebondir »

## D1 — Absence de rebond (Face vs Coin)

- **Famille** : face vs coin
- **Symptôme joueur** : la balle traverse la brique sans changer de direction.
- **Cause** : `game/neon.js:198` — la collision est détectée (`collides()`) mais aucune modification de `ball.vx` ou `ball.vy` n'est effectuée.
- **Invariant violé** : Toute collision avec un obstacle doit entraîner un rebond selon la normale de la face touchée.
- **Déclencheur** : toute collision avec une brique.
- **Attendu** : `vy` inversé si contact haut/bas, `vx` inversé si contact gauche/droite, les deux si contact coin.
- **Référence** : https://gamedev.stackexchange.com/ — Détermination de la normale de collision pour le rebond.
- **Cas test** :
  ```js
  test('D1 - Ball should bounce off the top of a brick', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + brick.h / 2;
    state.ball.vx = 0;
    state.ball.vy = -260;
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vy > 0, true);
    assert.strictEqual(state.ball.vx, 0);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced DOWN`
- **Discrimine** : une correction qui inverserait systématiquement `vy` même lors d'un choc latéral.
- **Vert quand** : la balle repart dans la direction opposée à la face touchée.

## D2 — Effet Collant (Sticking)

- **Famille** : Collant
- **Symptôme joueur** : la balle peut vibrer à l'intérieur d'une brique ou mettre plusieurs frames à en sortir.
- **Cause** : absence de repositionnement de la balle hors de l'AABB de la brique après le rebond.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle de la brique.
- **Déclencheur** : collision où le recouvrement est > 0.
- **Attendu** : `state.ball.x` ou `state.ball.y` ajusté pour que `collides(ball, brick)` soit faux immédiatement après le rebond.
- **Référence** : LearnOpenGL - Collision resolution (Minimum Translation Vector).
- **Cas test** :
  ```js
  test('D3 - Ball should be repositioned after bounce (No sticking)', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + brick.h / 2;
    state.ball.vx = 0;
    state.ball.vy = -260;
    frame(mockCtx, state);
    assert.strictEqual(state.ball.y - 7 <= brick.y, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should be pushed out of the brick`
- **Discrimine** : une correction qui inverse la vitesse mais laisse la balle à l'intérieur de la brique.
- **Vert quand** : la balle est repositionnée à l'extérieur de la brique.

## D3 — Traversée (Tunneling)

- **Famille** : Traversée
- **Symptôme joueur** : à haute vitesse, la balle saute complètement une brique.
- **Cause** : détection discrète basée sur la position finale de la frame.
- **Invariant violé** : Aucun obstacle franchi sans rebond, quel que soit le pas.
- **Déclencheur** : $ballSpeed(level) \times dt > (BRICK\_H + 2 \times BALL\_R)$. Pour $dt=0.05$, cela arrive au niveau 6+.
- **Attendu** : détection du franchissement entre $t$ et $t+dt$.
- **Référence** : Swept AABB collision detection.
- **Cas test** : (À implémenter en TDD : placer la balle telle qu'elle franchit la brique en un pas).
- **Rouge aujourd'hui** : (Invisible au niveau 1, mais mathématiquement certain au niveau 6).
- **Discrimine** : une détection purement discrète.
- **Vert quand** : la balle rebondit même si le pas est supérieur à la taille de la brique.
- **Révélé par** : D1 et D2 (le tunneling est la forme extrême du problème de collision).

