import assert from 'node:assert';
import { test } from 'node:test';
import { createState, frame } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  beginPath: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1 - Ball should bounce off the top of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 0;
  state.ball.vy = -260;

  frame(mockCtx, state);

  console.log('D1 Result:', {
    vy: state.ball.vy,
    y: state.ball.y,
    brickY: brick.y,
    brickH: brick.h,
    r: state.ball.r
  });
  assert.strictEqual(state.ball.vy > 0, true, 'Ball should have bounced DOWN');
});

test('D2 - Ball should bounce off the left side of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 2;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 260;
  state.ball.vy = 0;

  frame(mockCtx, state);

  console.log('D2 Result:', {
    vx: state.ball.vx,
    x: state.ball.x,
    brickX: brick.x,
    brickW: brick.w,
    r: state.ball.r
  });
  assert.strictEqual(state.ball.vx < 0, true, 'Ball should have bounced LEFT');
